// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer signer;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        signer = new Signer();
    }

    function testFuzz_property(address to) public {
        vm.assume(to != address(0));
        vm.assume(to != address(this));
        vm.assume(to != address(c));

        // Build a simple long call order whose maker is an ERC-1271 signer helper.
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(signer),
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 positionId = c.fillOrder(order, sig, floorAssetTokenIds);

        // The position is now owned by the caller (this test contract).
        require(c.ownerOf(positionId) == address(this), "setup failed");

        // Authorized transfer of the position to a fuzzed recipient.
        c.transferFrom(address(this), to, positionId);

        // General rule: after a successful transferFrom, the recorded owner of the
        // token is exactly the recipient.
        assertTrue(c.ownerOf(positionId) == to);
    }

    fallback() external payable {}
}

contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}
